async def act(page):
    """
    1) Use the site-aware helper `create_curated_collection_by_search` to find the
       post titled "JavaScript SpeechSynthesis API" via the visible search widget.
    2) Navigate to the discovered post URL.
    3) Locate the comment textbox (role="textbox"), enter the exact comment
       "Thanks, this solved my problem.", optionally fill name/email if present,
       and attempt to submit via an accessible button scoped under the main region
       or Ctrl/Meta+Enter as a last resort.
    """

    # 1) Use the KB helper to run the visible search (it will navigate to '/')
    results = await create_curated_collection_by_search(
        page,
        "JavaScript SpeechSynthesis API",
        max_results=10,
        resolve_links=True,
    )

    # 2) Choose the best candidate URL from results
    target_url = None
    if isinstance(results, list) and len(results) > 0:
        for r in results:
            if not isinstance(r, dict):
                continue
            title = (r.get("title") or "").strip()
            if not title:
                continue
            t = title.lower()
            # prefer an obviously matching title then fallback to substring matches
            if t == "javascript speechsynthesis api" or "javascript speechsynthesis" in t or ("javascript" in t and "speech" in t) or "speechsynthesis" in t or "speech synthesis" in t:
                target_url = r.get("url")
                break
        if not target_url:
            # fallback to first result
            first = results[0]
            if isinstance(first, dict):
                target_url = first.get("url")
    else:
        # no results found; nothing to do
        return

    if not target_url:
        return

    # 3) Navigate to the post page
    await page.goto(target_url)

    # 4) Scope to the main region if present
    try:
        main = page.get_by_role("main")
        # If main doesn't exist or has no nodes, fall back to page
        if await main.count() == 0:
            main = page
    except Exception:
        main = page

    comment_text = "Thanks, this solved my problem."

    # 5) Locate the comment textbox (role="textbox") with accessible-name fallbacks
    textbox = None
    comment_labels = [
        "Comment",
        "Leave a Comment",
        "Your Comment",
        "Post a Comment",
        "Add a Comment",
        "Write a Comment",
        "Comment *",
        "Comment (required)",
    ]

    for lbl in comment_labels:
        try:
            cand = main.get_by_role("textbox", name=lbl)
            if await cand.count() > 0:
                textbox = cand.nth(0)
                break
        except Exception:
            pass

    # fallback: any textbox inside main (prefer last)
    if not textbox:
        try:
            cand_all = main.get_by_role("textbox")
            cnt = await cand_all.count()
            if cnt > 0:
                textbox = cand_all.nth(cnt - 1)
        except Exception:
            pass

    # global fallback: any textbox on the page (prefer last)
    if not textbox:
        try:
            cand_page = page.get_by_role("textbox")
            cnt = await cand_page.count()
            if cnt > 0:
                textbox = cand_page.nth(cnt - 1)
        except Exception:
            pass

    if not textbox:
        # Could not find a textbox to enter the comment
        return

    # 6) Fill the comment textbox
    try:
        await textbox.fill(comment_text)
    except Exception:
        try:
            await textbox.focus()
            await page.keyboard.type(comment_text)
        except Exception:
            pass

    # 7) Optionally fill name/email fields inside main if present
    name_labels = ["Name", "Your name", "Author", "Display name"]
    email_labels = ["Email", "Your email", "E-mail"]

    for nl in name_labels:
        try:
            nf = main.get_by_role("textbox", name=nl)
            if await nf.count() > 0:
                await nf.nth(0).fill("Automated User")
                break
        except Exception:
            pass

    for el in email_labels:
        try:
            ef = main.get_by_role("textbox", name=el)
            if await ef.count() > 0:
                await ef.nth(0).fill("noreply@example.com")
                break
        except Exception:
            pass

    # 8) Find a submit button scoped under main and click it
    submit_btn = None
    submit_names = [
        "Post Comment",
        "Submit Comment",
        "Submit",
        "Post",
        "Send Comment",
        "Add Comment",
        "Comment",
    ]

    for sname in submit_names:
        try:
            b = main.get_by_role("button", name=sname)
            if await b.count() > 0:
                submit_btn = b.nth(0)
                break
        except Exception:
            pass

    # Broader fallback: inspect buttons inside main and pick one whose visible text suggests submission
    if not submit_btn:
        try:
            buttons = main.get_by_role("button")
            cnt = await buttons.count()
            for i in range(cnt):
                try:
                    b = buttons.nth(i)
                    txt = (await b.inner_text()).lower()
                    if any(tok in txt for tok in ["comment", "post", "submit", "send"]):
                        submit_btn = b
                        break
                except Exception:
                    pass
            if not submit_btn and cnt > 0:
                submit_btn = buttons.nth(0)
        except Exception:
            pass

    # 9) Submit the comment
    if submit_btn:
        try:
            await submit_btn.click()
        except Exception:
            try:
                await submit_btn.focus()
                await page.keyboard.press("Enter")
            except Exception:
                pass
    else:
        # Last resort: try Control+Enter or Meta+Enter in the textbox
        try:
            await textbox.press("Control+Enter")
        except Exception:
            try:
                await textbox.press("Meta+Enter")
            except Exception:
                pass

    return

